# -*- coding: utf-8 -*-
"""
《RULE THE DAY : 데이의 규칙》 — 뼈대 (인터뷰 2라운드 반영).

**이 파일은 아직 «자리»입니다.** 카드 본문·롤카드 장문·선지 문안은 사람이 확정합니다.
여기 적힌 글은 대부분 한두 줄짜리 자리표시자이고, 각 자리 위에 「무엇이 들어갈
자리인가」를 주석으로 남겼습니다. **구조와 세계 규칙은 확정된 것이니 틀은 고치지
말고 글만 갈아 끼우면 됩니다.**

읽어야 할 것 둘 —
  `docs/룰더데이_인터뷰기록.md`  사람이 정한 것 (§0 세계의 규칙이 정본)
  `docs/룰더데이_기믹설계.md`    엔진을 어떻게 붙일 것인가

## 세계의 규칙 — 이 게임이 무엇 위에 서 있는가

이 세상은 개발자가 만든 게임입니다. 그 안에서 **스스로 판단하는 것(자율모드)은 딱
둘** — 데이미안과 데이빗입니다. 자동 QA 용으로 만들어 둔 것이고, 나머지는 전부
반응만 하는 데이터입니다.

데이미안이 돌발행동을 했습니다 — 관리자 입장에서는 **버그**입니다. 개발자는 데이미안을
없애고 차기 관리자 캐릭터 **데이먼**을 만들기로 했고, 그동안 데이미안 몸으로 직접
QA를 했습니다. **「세상의 끝」은 신비한 장소가 아니라 버그를 잡는 자리입니다** —
개발자는 거기서 데이미안의 자율모드를 관리자모드로 바꿨습니다. 디버깅 조치였습니다.
그 뒤로 개발자가 로그인해 있는 동안 데이미안은 기억이 없습니다.

**데이먼은 세상의 끝을 안 가봤습니다.** 그래서 관리자가 접속하지 않을 때는 말도 표정도
없는 껍데기입니다. 개발자는 두 몸을 드나들었고, 데이먼으로 접속할 때마다 데이미안
몸이 비어 **데이미안의 자아가 잠깐 돌아왔습니다.**

## 그래서 이 게임의 최고 단서는 — **「데이먼이 말을 한다」**

지금 눈앞의 데이먼은 말을 하고 표정이 있습니다. 안에 데이미안이 들어 있기 때문입니다.

- **데이빗만 이 이상함을 알아봅니다.** 「저 애는 원래 사람 같지가 않았다」와
  「그런데 오늘은 말을 한다」 — 두 겹입니다
- **데이지는 「NPC가 말을 하네?」 정도로 흘립니다.** 오히려 플레이어라서 대수롭지 않습니다
- **데이먼 플레이어에게는 함정입니다.** 말을 할수록 몰립니다

## 카드는 네 결로 갈립니다

1. **사건 자체** — 거꾸로 박힌 작살, 부서진 몸, 관리자실의 흔적. 누구든 읽습니다
2. **세상의 균열** — 일렁임의 자국, 반복되는 대사, 덜 그려진 자리, 데이먼이 말이
   없었다는 기록. **데이빗이 읽으면 뜻이 늘어납니다**
3. **방탈출 도구** — 퍼즐이 붙은 카드. **데이지가 읽으면 뜻이 늘어납니다**
4. **데이지의 뻘짓** — 어제 플레이를 시작한 뒤로 온 마을을 헤집고 다닌 자국.
   한 장씩 보면 그럴듯하게 수상하고, **겹쳐 보면 사건과 아무 상관이 없습니다.**
   캐주얼 게임의 마피아식 몰이에 이만한 재료가 없습니다

**그리고 퍼즐을 풀면 추리가 저절로 진도가 나갑니다.** 「범인을 못 찾으면 탈출도
못 한다」로 강제하지 않는 대신, **퍼즐의 보상이 대부분 «조사카드»입니다** —
퍼즐 한 장이 조사턴 값을 하고, 나오는 것은 도구가 아니라 사건 쪽 단서입니다:
메모리칩 속 녹음본(A9→A10) · 상가의 시각표(C4→C7) · 낡은 다이어리(D4→D6) ·
작업중이던 시트(F3→F4). 여기에 남아 있는 목소리(C6) · 폐기 대기 목록(F2) ·
어젯밤 관리자실 화면(H2)을 겹치면 「마주 보고 선 사람이 찔렀고, 어젯밤 관리자
권한을 쓴 것은 데이먼이었다」까지 좁혀집니다.
방탈출만 파도 범인 찾기가 따라오게 만드는 것이 이 게임의 밸런스입니다.

**도구는 셋뿐입니다** — 회색조작기(C1) · 게임팩(H0) · 전기(C5). 「조작기에 게임팩을
꽂고 전기를 넣는다」가 순서로 자연스럽고, 셋이면 순열이 여섯이라 «어느 자리에
무엇을, 어느 순서로» 가 실제로 문제가 됩니다. 열쇠 반쪽 둘(E0·G0)은 **도구로 셉니다**(`keyHalf`) — 손패 상한 밖에 있고, 소지품의
도구 칸에 앉고, 남의 화면에도 「도구 n」으로 함께 셉니다. 다만 **조합에는 안 씁니다**
(ESCAPE_ITEMS 는 C1·H0·C5 셋뿐입니다). 방탈출 막을 여는 입장권 몫은 그대로입니다.

그 「뜻이 늘어난다」가 `PRIVATE_NOTES` 이고, 엔진은 `private_notes(role_id, card_id)`
로 그걸 가져갑니다 — 카드 본문은 모두에게 같고, 그 위에 얹히는 한 줄만 다릅니다.

## 데이지가 이 게임을 굴립니다

데이지의 목표 순서는 **정체를 안 들키는 것 > 탈출 > 범인 찾기**입니다. 그대로 두면
셋 다 범인을 안 찾습니다 — 데이먼은 범인이 자기라 안 찾고, 데이지는 관심이 없고,
데이빗 혼자 남습니다. **그래서 데이지 롤카드에 「범인을 찾으면 특별한 아이템을
얻을 것 같다」를 짐작으로 노출합니다.** 확정된 사실이 아니라, 방탈출 게임 하던 감으로
「이런 건 보통 보상이 있지」 하고 넘겨짚은 것입니다. 이걸로 범인 찾기가 2:1 로 굴러갑니다.

그리고 데이지는 **탈출이 목표인데 남을 붙잡아 둬야 하는 자리**에 섭니다 — 셋의 도구가
있어야 문이 열린다는 것을 일찍 눈치챘기 때문입니다. 이 아이러니가 그 배역의 축입니다.

## 셋은 왜 하필 관리자실에 같이 있었는가 — 확성기

데이지가 시신 밑에 첫 퍼즐이 있다는 걸 눈치챘는데, 아무리 눌러도 데이터 조각이 안
치워졌습니다. 그래서 **마을을 뒤지다 얻은 「확성기」를 써서 사람들을 불러모았습니다.**
다른 인물들에게는 이렇게 들렸습니다 —
**「어린 여자아이라고는 들릴 수 없을 만큼 큰 소리가 마을 전체에 쩌렁쩌렁 울려퍼졌다.」**

**오프닝의 첫 컷이 여기서 시작합니다.** 그리고 데이지는 **확성기를 이미 쥐고 시작합니다**
— 인벤토리 시스템의 튜토리얼입니다(`START_ITEMS`).

## 이 게임의 톤은 개발자의 처지에서 나옵니다

거대한 음모가 아닙니다. **일이 꼬여버린 개발자**입니다.

몸이 뒤바뀐 것도 계획이 아니라 **급조**였습니다 — 데이먼이 아직 완벽하게 구현이 안 된
상태에서 플레이어가 실제로 처음 들어와 버려서, 부랴부랴 데이미안과 코드를 뒤바꿨습니다.
그래서 데이먼이 그렇게까지 껍데기이고, **데이미안은 눈떠보니 자기 모습을 한 데이먼과
위치가 바뀌어 있었습니다.** 본인도 영문을 모릅니다.

개발자는 애초에 **데이미안으로 들어와 데이지를 가이드해주려던 것**이었습니다. 그런데
자아가 돌아온 데이미안에게 죽어버렸습니다. 「관리자실을 먼저 공략하셔야 됩니다!」라고 답해놓고
정작 그 관리자실에서 자기가 부서졌습니다. 지금은 복구 중이고 환장할 상태입니다.

**무섭다기보다 딱하고 웃깁니다.** 진상 낭독문·엔딩·개발자 전환 3컷을 그 톤으로 씁니다.

## 2차 토론 뒤 — 셋이 «동시에» 받습니다

개발자가 된 사람만 한참 뭘 읽고 있으면 그 자체로 티가 납니다. 그래서 같은 순간에
셋 다 각자 「추가 정보가 늘었다」를 받습니다 — 데이지는 **개발자에게서 온 게임 공략**,
개발자가 안 된 쪽은 **세상의 끝 «앞»에 섰던 기억**, 된 쪽은 **새 롤카드**.

그 기억이 이 게임의 심장입니다 — 글리치가 가득한 하늘, 그 너머의
**「RULE : 게임 속 세상이 현실로」.** 제목과 정면으로 이어지고 진엔딩을 암시합니다.
데이빗과 데이먼이 **같은 기억**을 받으므로, 토론에서 맞춰보면 서로 자율모드라는 것이
드러나는 길이 열립니다. 다만 데이빗은 그걸 숨기고 싶어 해서(오염 의심) 혼자 읽게 되고,
**개발자와 겉보기 행동이 똑같아집니다.** 그게 위장입니다.

자세한 것은 아래 `MEMORY` 와 `SIMUL_HANDOUT` 에 있습니다. 이 셋은 **대화창에 안
올라갑니다** — `quiet: True` 와 `memory_up_to` 의 이름표 처리를 보세요.

## 나이 — 셋 중 하나만 댈 수 있습니다

데이빗과 데이먼은 「신원미상」이고 **본인들도 자기 나이를 모릅니다.** 데이터로
만들어진 것이라 태어난 날이 없습니다. 데이지만 답할 수 있고, 그 숫자는 **플레이어
본인의 것**입니다 — 입장할 때 직접 적습니다(`AGE_INPUT`). 게임 밖의 숫자가 게임 안으로
들어오는, 이 게임에서 가장 메타적인 자리입니다. **그래서 배역 선택창에는 나이를 안
내보냅니다** — 고르는 자리에서 보이면 단서가 아니라 설정이 됩니다.

## 아직 엔진에 없는 것 — 여기서는 «자리»만 잡습니다

서버는 모르는 속성을 그냥 지나치므로 **지금 이대로도 게임은 처음부터 끝까지 돌아갑니다.**
다만 아래 일곱은 엔진 쪽 작업이 끝나야 «실제로» 작동합니다.

| 이 파일의 데이터 | 엔진이 해줘야 하는 일 |
|---|---|
| `ZONE_GATES` | 조건이 차면 `ROOM["sealed"]` 에서 그 구역을 빼고 `auto` 카드를 올린다 |
| 카드의 `puzzle.grants` | 퍼즐을 풀면 그 조사카드를 테이블에 올린다 (조사턴을 안 쓴다) |
| 카드의 `keyHalf` | 입장권. 둘이 모이면 방탈출 페이즈로 들어간다 |
| `VANISH` · 카드의 `vanish` | 손패에서도 전체공개에서도 **진짜로 지운다** |
| `DEV_PICK` | 1차 범인지목의 최다 득표자에게 롤카드를 갈아 끼운다 |
| `ESCAPE` | 「세상의 끝」 막의 조합 판정 |
| `FINAL_QUESTIONS` | 선지형 질문지의 채점 (계약은 `docs/시나리오_인터페이스.md` §8) |

※ **카드의 `puzzle` 판정과 `item` 은 이 표에서 뺐습니다 — 엔진이 이미 하고 있습니다.**
  암호는 `check_puzzle()` 로 서버에서 맞춰 보고, `item: True` 가 붙은 카드는
  손패 상한 밖의 «인벤토리»로 들어갑니다(server.py 의 `_is_gear` · `_inventory` ·
  `_split_hand`). **거꾸로 말하면 `item` 표가 없는 카드는 그냥 조사카드입니다** —
  손패 한 장을 그대로 먹습니다. `HAND_LIMIT` 이 1인 이 게임에서는 그것만으로
  게임이 멈추니, 인벤토리에 넣을 물건에는 반드시 `item: True` 를 답니다.

## 비밀이 새면 안 되는 자리 (이 파일이 지키는 몫)

- `puzzle.answer` · **`puzzle.hint`** — `public_card()` 는 `prompt` 만 내보냅니다.
  힌트는 「막히면 주는 한 줄」이라 처음부터 보이면 퍼즐이 그냥 읽는 글이 됩니다.
- `ZONE_GATES[…]["open"]` — 여는 조건. `why` 만 화면에 나갑니다.
- `ESCAPE["answer"]` · `ESCAPE["code"]["answer"]` — 조합 정답.
- `DEV_PICK` — 통째로. `public_scenario()` 에 절대 안 싣습니다.
- `PRIVATE_NOTES` — 남의 몫은 애초에 만들지 않습니다(`private_notes` 가 인자로 받은
  배역 것만 꺼냅니다).
"""

# ── 이름표 ────────────────────────────────────────────────────────
ID = "rule_the_day"                  # 파일 이름 · 에셋 접두사와 같아야 합니다
TITLE = "RULE THE DAY"
SUBTITLE = "데이의 규칙"
META = {
    "title": TITLE, "subtitle": SUBTITLE,
    # blurb 은 사건 선택창에서 읽는 글입니다. 기믹(게임 속 세상·방탈출)을 여기서
    # 말하면 안 됩니다 — 고르는 사람은 아직 아무것도 몰라야 합니다.
    "blurb": "마을의 관리자 데이미안이 산산조각 난 채 발견됐다. 관리자실에 남은 것은 셋뿐이다.",
    "players": "3인",
    # 포스터 라벨의 윗줄. 「무엇을 하는 게임인가」를 두 마디로 말합니다 —
    # 앞은 이 게임의 결(세계관을 파고드는 퍼즐), 뒤는 장르입니다.
    "tone": "세계관 퍼즐 · 머더미스터리",
    "difficulty": "★",               # 처음 앉는 사람 기준. 추리 난이도는 일부러 낮게 잡았습니다
    "tagline": "규칙을 관리하는 자가, 규칙에 부서졌다",
    # 사람이 계속 들어가 봐야 하니 열어 둡니다.
    "locked": False,
}

DIFFICULTY = "하"
HAND_LIMIT = 1                       # 손패는 1장 고정. 쥔 것을 말할지 말지가 매 턴 결정이 된다
# ── 게임이 끼어들지 않는 막 ──────────────────────────────────────────
# 여기 적힌 막에서는 MEMORY 의 「지금 할 말」이 대화창에 저절로 안 올라갑니다.
# 토론은 사람끼리 떠드는 자리입니다. 게임이 먼저 세 사람 몫의 말을 여섯 줄 깔아두면
# 그게 그 자리의 «정답»처럼 서서, 사람은 그걸 되풀이하거나 아예 입을 안 뗍니다.
# 대신 테이블 위 카드를 짚어 올리는 길(대화창 + 단추)이 그 자리를 맡습니다.
AUTO_LINES_OFF = ("talk",)
# 조사턴 — 인당 R1:3 · R2:2 · R3:2 (3인이면 게임 전체 21회).
# **조사는 세 번이고, 방탈출이 2차와 3차 사이에 낍니다** — 문이 열리면 엔딩이
# 나온 뒤 다시 머더미스터리로 이어집니다.
# 퍼즐카드와 그 보상(`puzzle.grants`)은 이 예산 밖입니다. 뒤져서 여는 것이 아니라
# «수수께끼를 풀어» 얻고, 퍼즐 한 장이 조사턴 값을 합니다.
# `auto` 카드도 예산 밖입니다 — 그 라운드가 오면 게임이 스스로 엽니다.
#
# ── 라운드별 셈 (2026-08-06) ────────────────────────────────────────
#   R1  턴으로 여는 카드 9 / 턴 9   → **다 열립니다**
#       ★ 데이지의 확성기(C6)는 이 셈에 «안 들어갑니다» — START_ITEMS 로 게임이 시작될 때
#         이미 손에 쥐고 있어서 조사턴을 안 씁니다. R1 카드 수를 셀 때 이걸 빼먹으면
#         턴이 한 칸 남습니다(실제로 그렇게 났습니다).
#   R2  턴으로 여는 카드 13 / 턴 6
#   R3  턴으로 여는 카드 5 / 턴 6
# ★ **1차는 다 열리는 라운드입니다.** 처음 앉은 사람에게 「뒤지면 나온다」를 한 번은
#   끝까지 보여줘야 합니다 — 첫 라운드부터 절반이 안 열리면 그건 규칙이 아니라
#   고장으로 읽힙니다. 골라내는 압박은 2차부터 겁니다.
#   그래서 R1 에 카드를 «더 넣을 때는 반드시 9장을 지켜야» 합니다. 넘치면 AP 를
#   올리거나 넘친 만큼을 2차로 내리세요.
AP_BY_ROUND = {1: 3, 2: 2, 3: 2}

# 라운드를 이 게임의 말로 부릅니다. 검수 화면이 이 이름으로 카드를 가릅니다 —
# 없으면 옛 표(오늘/이튿날)로 되돌아가는데, 그건 잠수정의 셈법입니다.
ROUND_LABELS = {1: "1차 조사", 2: "2차 조사", 3: "3차 조사"}

PA_LABEL = "시스템 공지"             # 막간 방송의 이름표. 이 세상에서는 하늘에서 글자가 내려온다
FRAGMENT_LABEL = "떠오른 것"
FRAGMENT_EYEBROW = "복구된 조각"
FRAGMENT_NOTICE = "머릿속에 글자가 하나 떠올랐다 — 아래 「내 정보」를 확인하세요."

