# ══════════════════════════════════════════════════════════════════
#  보드맵 — 조사 페이즈의 화면
# ══════════════════════════════════════════════════════════════════
# 조사할 때는 «표» 가 아니라 «자리» 를 봐야 합니다. 그래서 조사 페이즈는 판때기
# 그림 한 장을 깔고 그 위에 구역 핀을 얹습니다(지금의 조사현황 패널은 토론 쪽으로
# 갑니다 — 거기서는 「A구역에 아직 두 장 남았다」를 세는 것이 하는 일이라 표가 맞습니다).
#
# ★ nodes 의 값은 «그림 안에서의 백분율» 입니다. 그림(pending/맵판.md)에 적어 둔
#   자리와 같아야 합니다. 그림이 조금 어긋나게 나왔으면 그림을 다시 뽑지 말고
#   이 숫자를 옮기세요 — 고치는 쪽은 늘 이쪽입니다.
# ★ 잠긴 구역은 여기서 빼지 않습니다. 그림에는 여덟 칸이 다 그려져 있고, 화면이
#   아직 안 열린 자리 위에 노이즈를 덮습니다. 덮는 것이 «글리치» 라는 것 자체가
#   이 게임의 말입니다 — 안 그려진 자리가 아니라 «가려 둔 자리» 니까요.
# ── 판때기 ────────────────────────────────────────────────────────
# ★ 한 장짜리 그림으로 뽑으려다 물렀습니다. 그림 하나로 뽑으면 여덟 칸의 «그림»과
#   화면이 얹는 «핀»이 늘 어긋날 위험을 안고 가야 하고, 구역이 숨었다 열릴 때마다
#   판이 통째로 바뀌어야 합니다. 지금은 화면이 구역 그림들을 그 자리에 놓고
#   CCTV 화면처럼 만듭니다 — 그러면 숨은 구역은 애초에 안 걸리고, 잠긴 구역은
#   그 화면만 노이즈가 됩니다. 이 게임의 세계관과도 맞습니다. 이 마을은 누가
#   «보고 있는» 곳이고, 모니터 정원이 이미 그 말을 하고 있습니다.
