# ── 해금 공간 ─────────────────────────────────────────────────────
# **`ZONE_LOCK` 은 안 씁니다.** 그건 라운드 숫자로만 열리고, 잠겨 있다는 것이 화면에
# 아예 안 뜹니다(기믹설계서 ①). 대신 게임이 시작될 때 이 키들을 `ROOM["sealed"]` 에
# 넣어 두고, 조건이 차면 빼는 방식입니다 — `sealed` 는 지도·현황판·조사 거절 문구가
# 이미 다 그리고 있습니다.
#
#   opensFrom  어느 구역을 파야 이어지는가 (사람이 읽는 몫 · 지도에도 같은 값)
#   why        잠겨 있을 때 눌러 보면 읽히는 줄. **화면에 나가도 되는 유일한 것**
#   open       여는 조건. cards = 그 카드들이 «전체공개»됐는가. 여럿이면 AND
#              ★ 이건 절대 화면에 안 나갑니다. 알면 카드를 감출 이유가 사라집니다
#   opened     열리는 순간 대화창에 뜨는 한 줄
#   auto       열리자마자 저절로 테이블에 오르는 카드 (조사턴을 안 쓴다)
#
# ※ why · opened 문안은 자리표시자입니다.
