# ── 알리바이 대화록 ───────────────────────────────────────────────
# 게임이 열릴 때 대화창에 한 줄씩 흘러 들어갑니다.
#
# ★ 첫 줄이 이 게임의 첫 압박입니다. **데이지가 제1발견자**이고, 시신을 보고 한
#   첫마디가 저것입니다 — 사람이 죽어 있는데 아무 감정이 없습니다.
# ★ 그다음이 **데이빗의 일렁임 증언**입니다. 두 증언이 겹쳐야 시간대가 섭니다.
# ★ 그리고 마지막 두 줄이 **이 게임 최고의 단서**입니다 — 데이먼이 말을 하고 있고,
#   그걸 이상하게 여기는 사람은 데이빗뿐입니다. 데이지는 흘립니다.
#   게임이 시작되자마자 이 신호가 대화창에 깔려 있어야, 뒤에 나오는 카드가 걸립니다.
# ★ **사건 시각을 여기서 공개합니다 — 어젯밤 23:20, 마을 전체의 불빛이 한 번
#   깜빡였습니다.** 진상문에 원래 있던 문장(「그 순간 세상의 불빛이 한 번 깜빡였다」)을
#   공개 사실로 끌어올린 것입니다. 이 세상의 사건은 «시스템 이벤트»로 일어나고 그건
#   모두의 화면에 뜨므로, 검시도 부검도 없이 셋이 같은 시각을 압니다.
#   그래야 1차 토론의 첫 문장이 저절로 정해집니다 — 「열한 시 이십 분에 어디 있었나.」
#   데이지에게는 그게 **렉**으로 보였다는 것이 이 게임다운 한 줄입니다.
# ★ **셋이 다 «그때 어디 있었는지»를 한 번씩 말합니다. 그리고 셋 다 숨깁니다.**
#   참말을 하면 저마다 잃을 것이 있어서입니다 — 알리바이를 증명하려면 자기 비밀을
#   내놔야 하고, 그 대가가 이 게임의 1차 토론입니다.
#   **숨기는 «모양»이 셋 다 다릅니다** — 데이먼은 자리를 바꿔 말하고, 데이지는
#   확인할 수 없는 자리를 대고, 데이빗은 자리는 참말이되 그 앞의 두 시간을 뺍니다.
#     데이먼   「잠수함」        실제는 관리자실. 참말하면 자기가 죽였다는 것이 드러난다
#     데이빗   「관리자실 바깥」  ← **이건 참말입니다.** 23:05 에 기록보관소를 나와
#                               걷던 중이었으니까요. 그가 감추는 것은 «자리»가 아니라
#                               **그 앞의 두 시간**입니다 — 죽은 데이미안을 두 시간
#                               캐고 있었다는 것. 그래서 그는 거짓말을 하는 것이 아니라
#                               **말하지 않는 쪽**으로 감춥니다. 출입기록이 그 두 시간을
#                               그대로 찍어 놓아서, 그 방식은 1차에 깨집니다.
#     데이지   「이곳저곳·바다 쪽」실제는 아케이드상가. 참말하면 어제 만든 사람과 직접
#                               이야기했다는 것과 확성기의 출처가 드러난다. 바다 쪽은
#                               **아직 잠긴 구역이라 아무도 확인할 수 없는 자리**다
#   셋을 동시에 거는 것이 기록보관소의 출입기록(B9)입니다. 기록은 참말만 합니다.
#   데이빗의 줄은 데이지의 물음에 «대답하지 않은 뒤»에 옵니다 — 답이 아니라
#   자기 자리를 대는 것이라, 그 침묵을 사이에 두어야 결이 맞습니다.
#   (설계 전문: pending/rule_the_day/타임라인.md)
# ★ **`stop` 은 하나만 둡니다** — 「그러고 나서 각자 자기소개가 시작되었다.」 앞입니다.
#   여기까지가 «시신 앞에서 오간 말» 한 덩어리라, 중간에 끊으면 주고받는 맥이 끊깁니다.
#   첫 줄부터 데이지의 「저는 한참 뒤에 왔어요」까지 쭉 흐르고, 결이 바뀌는
#   자기소개 앞에서만 한 번 멈춥니다.
# ※ 나머지 문안은 자리표시자입니다.
ALIBI_HEAD = "각자가 한 말을 그대로 옮긴 것이다 — 참인지는 아무도 모른다."
