# **조사는 세 번이고, 방탈출이 2차와 3차 사이에 낍니다.** 문이 열리면 엔딩이 한 번
# 나온 뒤 다시 머더미스터리로 이어집니다 — 그래서 방탈출 뒤에 3차 조사가 남습니다.
#
#   1  오프닝
#   2  1차 조사      round 1
#   3  1차 토론      round 1
#   4  1차 범인지목   ← 소지품 압수 + 여기서 개발자가 정해진다
#   5  2차 조사      round 2
#   6  2차 토론      round 2
#   7  방탈출        ← 열쇠 반쪽 둘을 아무도 못 모았으면 이 막은 «안 나온다»
#   8  3차 조사      round 3   ← 이 막이 열릴 때 세상이 복구된다(VANISH)
#   9  3차 토론      round 3
#   10 종막 — 지목과 질문지
#   11 엔딩
#
# ★ 「1차 범인지목」이라는 이름을 그대로 씁니다. **종막의 지목과 다른 것**이라는
#   것이 이름에서 보여야 합니다 — 이쪽은 지목당한 사람의 소지품이 압수되고(BELONGINGS),
#   최다 득표자가 개발자에게 덮어써지는 자리입니다(DEV_PICK).
#
# ★ **7막 「방탈출」은 건너뛸 수 있는 막입니다.** `skipUnless` 가 그 계약입니다 —
#   열쇠 반쪽 둘(E0 하늘 · G0 바다)이 **아무의 인벤토리에도 없으면 이 막을 통째로
#   지나갑니다.** 문 앞까지 갔다가 못 여는 것이 아니라, 애초에 문이 안 열립니다.
#   판정은 엔진 쪽 일이고 여기 있는 것은 조건 데이터뿐입니다
#   (계약: `docs/시나리오_인터페이스.md` §3).
#
# ★ 10막이 «종막»입니다. 엔진에서는 두 막으로 나뉩니다 — `final` 이 지목표와
#   질문지를 받고, `reveal` 이 엔딩·진상·점수를 냅니다(점수와 칭호는 `reveal`
#   막에서만 뜹니다). 사람이 읽는 순서로는 둘이 이어진 하나의 종막입니다.
#
# ★ 막을 하나 끼워도 조사 라운드는 안 밀립니다 — 엔진이 seq 가 아니라 페이즈의
#   round 를 봅니다.
#
# GM 지문에는 «게임을 어떻게 굴리는가»만 적습니다 — 무엇이 수상한지는 안 적습니다.
