# ══════════════════════════════════════════════════════════════════
#  배점 — **자동으로 판정할 수 있는 것만 셉니다**(채점자가 없는 게임입니다)
# ══════════════════════════════════════════════════════════════════
# 작업목록 §7-e·7-f 의 배점표입니다.
#
# ★★ **개발자는 자기 점수를 못 얻습니다.** 대신 «다른 두 사람의 점수 합»이 자기
#   점수가 되고, 개발자인 것을 맞힌 사람 수만큼 **고정 감점**이 붙습니다.
#
#       개발자 점수 = 다른 둘의 합 − (맞힌 사람 수 × 20)
#
#   이렇게 두면 세 가지가 한꺼번에 풀립니다 —
#   ① 판정할 사람이 필요 없습니다. 발언을 사람이 보지 않고 시스템이 셉니다.
#   ② 정보 우위가 유리함이 안 됩니다. 다 아는데 자기 점수를 남이 만듭니다 —
#      말을 못 하고, 남이 스스로 도달하게 밀어야 합니다.
#   ③ 데이먼이 개발자가 된 게임도 안 무너집니다. 자기 죄를 남이 밝혀야 점수가 오릅니다.
#   맞힌 사람이 하나뿐일 때 그 사람이 1등이 되는 것도 **그대로 둡니다** — 그게 더
#   긴장감 있습니다(§7-f).
#
# ※ 질문지 문항의 배점 정본은 `FINAL_QUESTIONS[…]["points"]` 입니다. 아래
#   `questions` 는 그 요약이고, 파일 끝에서 둘을 다시 맞춥니다.
SCORE_RULES = {
    "puzzle_each": 3,        # 퍼즐 한 장을 푼 사람에게
    "accuse_hit": 5,         # 종막 지목이 진범과 맞으면
    "escape_ok": 12,         # 방탈출 성공 — 셋 모두에게
    "escape_spend": -3,      # 문에 꽂은 도구 하나당 — 꽂은 사람이 잃는다
    # ── 각자의 ③번 «비밀» ───────────────────────────────────────
    # ★★★ **셋 다 같은 짜임입니다**(2026-08-09, 사람 결정) — 목표 셋 중 마지막
    #   하나가 «들키면 깎이는» 자리이고, **짚은 사람 하나당** 붙습니다.
    #   개발자가 짚은 것은 안 셉니다 — 개발자는 처음부터 다 알고 있으니까요.
    #   그래서 개발자가 «있는» 판에서는 짚을 수 있는 사람이 하나뿐이라 최대 -5,
    #   개발자가 «없는» 판에서는 둘이라 최대 -10 입니다.
    # ★ **인당으로 세는 것이 요점입니다.** 한 사람에게 들킨 뒤에도 남은 한 사람
    #   앞에서는 계속 연기할 이유가 남습니다 — 「이미 들켰으니 다 말해버리자」가
    #   안 나옵니다.
    "secret_per_hit": -5,
    "secret_dev_counts": False,   # 개발자가 짚은 것은 세지 않는다
    "secrets": {
        "david": "그날 세상의 끝에서 돌아섰다 — 넘지 않았다",
        "damon": "정체가 데이미안이다",
        "daisy": "바깥에서 들어온 «플레이어»다",
    },
    # 옛 이름. 데이지 몫이 위 secrets 로 옮겨 갔습니다 — 옛 배선이 이 키를 읽고
    # 있어서 값만 남겨 둡니다.
    "daisy_exposed": -5,
    # ── 질문지 ──────────────────────────────────────────────────
    "questions": {"q1": 6, "q2": 8},
    "q1_bonus_dayst": 1,     # Q1 에서 「데이미안」을 고른 사람에게 얹는다
    # ── 개발자 ──────────────────────────────────────────────────
    # 옛 이름. 값은 아래 dev.penalty_per_hit 와 같은 것입니다 — 「한 사람에게
    # 들킬 때마다 고정 20점」. 옛 배선이 이 키를 읽고 있어서 남겨 둡니다.
    "dev_exposed": -20,
    "dev": {
        "own": 0,                        # 자기 목표·퍼즐로는 점수를 못 얻는다
        # ★★ **밑돈이 «합»에서 «절반»으로 바뀌었습니다**(2026-08-09, 사람 결정).
        #   합으로 두면 개발자가 언제나 1등이라 다투는 자리가 없었습니다. 절반이면
        #   저들을 밀어주는 이유는 그대로인데 순위가 열립니다.
        # ★ 감점도 -20 에서 **-5** 로 내렸습니다 — 다른 배역의 비밀과 같은 눈금입니다.
        "base": "half_others",           # 다른 두 사람의 «최종 점수 합»의 절반
        "penalty_per_hit": -5,           # 개발자를 맞힌 사람 한 명당
        "hit_from": "q2",                # 「맞혔다」의 판정은 질문지 Q2 로만 한다
        # ★ 개발자에게는 하나가 더 있습니다 — 「캐릭터들이 자기가 무엇인지 깨닫지
        #   못하게 한다」. 깨달은 사람 하나당 -5 입니다. 데이지의 ③과 정확히 같은
        #   방향이라, 둘이 서로 모른 채 한편이 됩니다.
        "awake_per_hit": -5,
        "formula": "sum(others)/2 - 5*devHits - 5*awake",
        "formulaKo": "개발자 점수 = (다른 두 사람의 점수 합 ÷ 2)"
                     " − (개발자를 맞힌 사람 수 × 5) − (자기가 무엇인지 깨달은 사람 수 × 5)",
        # 바닥(하한)은 아직 안 정했습니다. 정하면 숫자를 넣으세요 — None 이면 하한 없음.
        "floor": None,
        # 개발자가 «안 들어온 게임»에서는 이 규칙 자체가 안 돌아갑니다(§7-h).
        "noDev": "개발자가 없는 게임에서는 셋 다 자기 점수를 그대로 셉니다.",
    },
    "note": "goals 의 p 는 자동 판정이 되는 것만 더한다. 나머지는 진행자가 읽어주기만 한다.",
}

