# ══════════════════════════════════════════════════════════════════
#  조사카드
# ══════════════════════════════════════════════════════════════════
# ※ text 는 전부 «보이는 것만» 적은 짧은 자리표시자입니다. 판단은 안 적습니다 —
#    무슨 뜻인지는 앉은 사람이 정합니다. hint 도 결론이 아니라 「이 카드로 무엇을
#    물어야 하는가」까지만 적습니다.
#
# **카드가 네 결로 갈립니다.** `vein` 키에 그 결을 적어 두었습니다(엔진은 안 씁니다 —
# 원고를 고치는 사람이 균형을 볼 수 있게 두는 표시입니다).
#
#   "case"   사건 자체.        누구든 읽는다
#   "glitch" 세상의 균열.      **데이빗이 읽으면 뜻이 늘어난다** (PRIVATE_NOTES)
#   "tool"   방탈출 도구.      **데이지가 읽으면 뜻이 늘어난다**
#   "noise"  데이지의 뻘짓.    한 장씩 보면 그럴듯하게 수상하고,
#                              **겹쳐 보면 사건과 아무 상관이 없다** (C5 가 그 자리)
#
# 이 게임에만 있는 키들 (엔진은 아직 모르는 자리표시자입니다):
#
#   puzzle {"prompt","answer","hint"}
#       암호를 풀어야 열립니다. **prompt 만 화면에 나갑니다** — answer 는 물론이고
#       hint 도 안 나갑니다(몇 번 틀린 사람에게만 여는 것이 엔진 쪽 일입니다).
#
#   item True
#       방탈출 도구. 상한 없는 인벤토리로 들어가고, 증발에도 안 사라집니다.
#       ★ **도구는 셋뿐입니다** — `C1 회색조작기` · `H0 게임팩` · `C5 전기`.
#       「조작기에 게임팩을 꽂고 전기를 넣는다」가 순서로 자연스럽고, 셋이면 순열이
#       여섯이라 마지막 자리 문제가 실제로 문제가 됩니다. 여기에 하나를 더 다는
#       순간 그 셈이 무너지니, **도구를 늘리지 마세요.**
#
#   keyHalf True
#       **입장권입니다. 도구가 아닙니다.** `E0 하늘 열쇠 반쪽` · `G0 바다 열쇠 반쪽`
#       둘뿐이고, 둘이 다 모여야 방탈출 막(7막)이 열립니다 — 하나라도 없으면 그 막을
#       통째로 지나갑니다(PHASES 7막의 `skipUnless`). 문에 꽂는 것이 아니라 문
#       앞까지 가는 몫이라 도구와 따로 셉니다.
#
#   puzzle.grants "카드id"
#       **퍼즐을 풀면 나오는 조사카드.** 도구가 아닌 퍼즐은 전부 이쪽입니다 —
#       퍼즐이 조사의 지름길이 되고, 퍼즐 한 장이 조사턴 값을 합니다.
#       A9→A10 · C4→C7 · D4→D6 · F3→F4.
#
#   vanish 8
#       **8막(3차 조사가 열릴 때) 이 카드가 세상에서 사라집니다.** `gone` 과 뜻이 다릅니다 —
#       `gone: n` 은 「n라운드부터 이제 못 연다」일 뿐이라 이미 손에 쥔 것도,
#       이미 전체공개된 것도 그대로 남습니다. 「흔적 없이 사라진다」는 그것으로
#       안 됩니다. 엔진에 `_vanish(seq)` 가 따로 필요하고, 무엇을 없앨지는
#       아래 VANISH 표가 정본입니다. 카드 쪽 `vanish` 는 검수하는 사람이 카드만
#       봐도 알 수 있게 같은 값을 한 번 더 적어둔 것입니다.
#       `gone` 은 그 엔진이 붙기 전까지의 임시 방편으로 같이 답니다.
#       ★ `item: True` 인 도구에는 절대 안 답니다.
