# ★ 데이지의 확성기가 이것입니다 — 오늘 아침 셋을 불러모은 물건이고, 동시에
#   인벤토리 시스템의 튜토리얼입니다. 엔진이 `ROOM["items"]` 를 만들 때 여기서
#   초기값을 읽으면 됩니다. 카드 쪽 `startWith` 는 검수용으로 같은 값을 적어둔 것입니다.
# ══════════════════════════════════════════════════════════════════
#  소지품 — 1차 범인지목에서 최다 득표한 사람이 그 자리에서 압수당합니다
# ══════════════════════════════════════════════════════════════════
# ★ 이 규칙은 지목 «전에» 전원에게 알립니다. 위험을 알고도 이름을 부르게 하는 것이
#   이 게임의 압박이고, 모르고 당하면 그냥 사고입니다.
# ★ 데이지의 확성기가 열리면 「첫 고객 특별지급」 스티커가 같이 나옵니다 —
#   이 마을 물건이 아니라 «이 마을에 온 손님» 에게 준 물건이라는 뜻입니다.
#
# ★ **칸 이름은 `title` 입니다**(`name` 이 아닙니다). 엔진의 `_belongings_public()` 이
#   `title` · `spot` · `text` · `hint` 만 꺼내 갑니다 — `name` 으로 적으면 초상 옆
#   제목 띠가 통째로 비고, 압수 공지도 「「」이 나왔습니다」로 나갑니다.
#
# ★★ **소지품 문안은 «물건 설명»이 아니라 «이 사람과 그 물건의 내력»입니다.**
#   생김새는 조사카드가 이미 적고 있습니다(확성기는 C6). 여기에 같은 것을 또 적으면
#   데이지의 「추가 정보」에서 소지품 장과 C6 장이 나란히 서서 **같은 글이 두 번**
#   보입니다 — 실제로 그렇게 보이던 것을 고친 자리입니다.
BELONGINGS = {
    "david": {
        "title": "세상의 끝에서 찍은 사진",
        "text": "끊긴 하늘 앞에 둘이 나란히 서 있다. 데이빗과 데이미안다.\n"
                "뒤쪽 하늘이 자로 그은 것처럼 네모나게 끊겨 있다.",
        "react": [
            {"who": "david", "text": "……그건 아주 옛날 겁니다."},
        ],
    },
    "damon": {
        "title": "네임택",
        "text": "손바닥만 한 이름표다. 「데이미안 [Legacy]」라고 찍혀 있다.\n"
                "가장자리가 닳아 있다. 오래 들고 다닌 물건이다.",
        "react": [
            {"who": "damon", "text": "……아버지 겁니다."},
        ],
    },
    # ★★ 이 물건이 이 게임에서 제일 위험한 소지품입니다. 압수되면 **「어제 주웠다」와
    #   「오늘 아침에 처음 썼다」가 그 자체로 압박이 됩니다** — 어제 온 사람이 어제
    #   마을을 헤집고 다녔다는 것과, 사람들을 그 방으로 부른 것이 자기라는 것이
    #   한 장에 같이 적혀 있습니다. 진상(플레이어라는 것)은 한 글자도 안 적습니다.
    #   생김새는 조사카드 C6 이 적으니 여기서는 «어디서 얻었고 어떻게 썼는가»만 씁니다.
    "daisy": {
        "title": "확성기",
        "text": "어제 마을을 둘러보다 아케이드상가 경품 더미에서 주워 온 것이다.\n"
                "손잡이에 스티커가 붙어 있다 — 「첫 고객 특별지급」.\n"
                "주운 뒤로 줄곧 품에 있었고, 오늘 아침 관리자실에서 처음 대고 말했다.\n"
                "사람을 불러모으려고 그랬다고 한다.",
        # ★ 두 줄로 나눕니다. 첫 줄은 순순히 인정하는 말이고, **둘째 줄에서 이 세상에
        #   없는 말이 한 번 새어 나옵니다** — persona 의 「가끔 이 세상에 없는 단어를
        #   쓴다」가 실제로 터지는 자리입니다. 본인이 곧바로 고쳐 말하는 것까지가 한 덩어리고,
        #   그 «고쳐 말함»이 오히려 걸립니다.
        "react": [
            {"who": "daisy", "text": "어제 주운 거예요. 오늘 아침에 처음 써 봤고요."},
            {"who": "daisy", "text": "이거 대고 말하면 맵 전체에 공지가 올라가서… 아, 마을 전체요."},
        ],
    },
}
BELONGINGS_ORDER = ["david", "damon", "daisy"]

# ── 1차 지목에서 자기 이름을 적을 수 있는가 ────────────────────────
# **적을 수 있습니다.** (사람 결정: 「추리는 자유다」)
#
# 한때 진행 지문(4막 `gm`)이 「자기 자신은 못 찍습니다」라고 적고 있어서 그쪽으로
# 맞췄다가, 지문 쪽을 고치는 것으로 되돌렸습니다. 이 게임에서는 자기를 적는 것도
# 하나의 수다 — 셋뿐인 판에서 자기 이름을 적는 것은 「나는 아니다」를 뒤집어 보이는
# 행동이고, 실제로 그렇게 둘 이유가 있습니다.
#
# 엔진 기본값도 «적을 수 있다» 입니다. 막고 싶은 시나리오만 False 를 적으면
# 서버가 물리고(accuse_interim), 화면은 목록에서 그 이름을 뺍니다(renderAccuse).
ACCUSE_SELF = True

START_ITEMS = {rid: [c["id"] for c in CARDS if c.get("startWith") == rid]
               for rid in ("david", "damon", "daisy")}

# ── 입장권 ────────────────────────────────────────────────────────
# 열쇠 반쪽 둘. **도구가 아닙니다** — 문에 꽂는 것이 아니라 문 앞까지 가는 몫이라
# 방탈출 조합(ESCAPE_ITEMS)과 따로 셉니다. 둘이 다 모여야 7막이 열리고, 하나라도
# 없으면 그 막을 통째로 지나갑니다.
#
# 정본은 카드의 `keyHalf` 표시입니다. 막의 조건이 그것과 어긋나면 「막이 영영 안
# 열린다」 같은 사고가 나므로, 여기서 7막의 skipUnless 를 카드 쪽 값으로 다시 맞춥니다.
KEY_HALVES = [c["id"] for c in CARDS if c.get("keyHalf")]
for _p in PHASES:
    if _p.get("skipUnless", {}).get("inventoryHas") is not None:
        _p["skipUnless"]["inventoryHas"] = list(KEY_HALVES)
del _p

