# ══════════════════════════════════════════════════════════════════
#  방탈출 — 7막. **열쇠 반쪽 둘이 모여야 열리는 막입니다**
# ══════════════════════════════════════════════════════════════════
# ★ 이 막은 **안 나올 수도 있습니다.** 열쇠 반쪽 둘(E0·G0)이 아무의 인벤토리에도
#   없으면 7막을 통째로 지나갑니다 — 조건은 PHASES 7막의 `skipUnless` 에 있고,
#   판정은 엔진 쪽 일입니다.
# ★ 문이 열리든 안 열리든 게임은 이어집니다 — 8막에 조사가 한 번 더 남아 있습니다.
#
# 경계에 문이 하나 있고 자리가 셋입니다. **서로 다른 세 사람의 도구가 하나씩**
# 들어가야 열립니다(`eachOne`). 한 사람이 셋을 다 꽂으면 안 열립니다.
#
# ★ **도구는 셋뿐입니다** — 회색조작기(C1) · 게임팩(H0) · 전기(C5).
#   「조작기에 게임팩을 꽂고 전기를 넣는다」가 순서로 자연스럽고, 셋이면 순열이
#   여섯이라 «어느 자리에 무엇을» 이 실제로 문제가 됩니다.
#
# ★ 신비한 자리가 아닙니다. **정비용 출입구**입니다 — 규칙시험실과 같은 결로 읽혀야
#   합니다. 개발자가 버그를 잡으러 드나들던 문이고, 그래서 열 수 있습니다.
#
# ★ 「점수를 포기하겠습니다」 버튼을 따로 두지 않습니다. **조합에 자기 도구를 내는
#   것 자체가 포기입니다** — 꽂은 사람은 그 도구 점수를 잃고(SCORE_RULES), 성공하면
#   셋 모두가 크게 얻습니다. 그래서 「내 점수만 보면 손해, 셋이 다 내면 이득」이
#   규칙 하나로 성립합니다. 이게 이 게임의 변주입니다.
#
#   locked/unlocked  잠긴 채로 들어설 때 · 열쇠 반쪽 둘이 맞물렸을 때
#   keys    입장권(열쇠 반쪽). 정본은 카드의 `keyHalf` = KEY_HALVES 입니다
#   slots   자리. label 이 도구 생김새와 맞물립니다 — 읽으면 알 수 있어야 합니다
#   answer  어느 자리에 어느 도구가 들어가는가. ★ 서버에만 있습니다
#   code    자리를 다 채운 뒤의 마지막 한 문제. `require` 를 켤 때만 붙습니다 —
#           ★ 지금은 **더미**라 꺼 둡니다. 실제 문제는 나중에 제대로 잡습니다
#   tries   몇 번까지 틀려도 되는가 · miss 틀렸지만 아직 안 닫혔을 때
#   ok/no/shut/short  열림 · 닫힘 · 못 푼 채로 떠남 · 낼 것이 모자람
#
# ※ 키 이름은 `docs/시나리오_인터페이스.md` §8-c 의 계약을 그대로 씁니다.
# ※ 문안과 정답은 전부 자리표시자입니다.
ESCAPE = {
    "need": 3,
    "eachOne": True,                     # 서로 다른 세 사람이 하나씩
    # ── 들어가는 몫 — 입장권 ────────────────────────────────────
    # 열쇠 반쪽 둘을 «장착»해야 문틀이 뜹니다. 반쪽은 문에 꽂는 도구가 아닙니다 —
    # 문 앞까지 가는 몫이라 조합 후보에서 빠집니다.
    "keys": ["E0", "G0"],
    "locked": "세상의 끝... 이 보인다. 하지만 잠겨 있다.",
    "unlocked": "반쪽 둘을 맞대자 잘린 면이 정확히 물린다.\n"
                "잠긴 것이 한 번 덜컹였다.",
    "intro": "경계에 정비용 문틀 하나가 서 있다. 꽂는 자리가 셋이다.",
    # 자리 이름이 도구 생김새와 맞물립니다 — 읽으면 알 수 있어야 합니다.
    "slots": [
        {"id": "s1", "label": "손잡이 자리", "note": "쥐고 움직이는 것이 붙을 자리다."},
        {"id": "s2", "label": "네모난 홈", "note": "납작하고 네모난 것이 꽂힐 자리다."},
        {"id": "s3", "label": "두 갈래 단자", "note": "금속 두 갈래가 나와 있다."},
    ],
    # ★ 새면 안 되는 것. 자리 이름과 「무엇이 꽂혔는가」까지만 화면에 나갑니다.
    #   조작기 → 게임팩 → 전기. 도구가 셋이라 순열이 여섯입니다.
    "answer": {"s1": "C1", "s2": "H0", "s3": "C5"},
    # ★ 더미라서 `require: False` 입니다 — 켜면 마지막에 이 문제가 한 번 더 붙습니다.
    "code": {
        "prompt": "[더미] 세 자리를 채우면 숫자 세 개가 뜬다. 순서대로 눌러라.",
        "answer": ["123"],
        "hint": "[더미] 꽂은 순서 그대로다.",
        "require": False,
    },
    "tries": 1,                          # 한 번 틀리면 문이 닫힌다
    "ok": "세 자리가 동시에 물렸다. 문이 열린다.\n"
          "그 너머에는 아무것도 그려져 있지 않다 — 그런데 발이 들어간다.",
    "no": "자리는 다 찼는데 아무 일도 일어나지 않는다.\n"
          "무언가가 제자리에 있지 않다.",
    "shut": "문틀이 그대로 서 있다. 아무도 손대지 않았다.",
    "short": "꽂는 자리가 셋인데 낼 수 있는 것이 모자란다.\n"
             "문은 열리지 않는다.",
}
# 입장권 목록의 정본은 카드의 `keyHalf` 입니다. 여기서 다시 맞춰 둡니다.
ESCAPE["keys"] = list(KEY_HALVES)

