# ══════════════════════════════════════════════════════════════════
#  비주얼노벨
# ══════════════════════════════════════════════════════════════════
# img 는 assets/rule_the_day_opening_{img}.webp 를 찾습니다. 파일은 아직 없습니다 —
# 없으면 화면만 어둡게 뜨고 글은 그대로 나옵니다. **img 키는 여기서 확정합니다.**
# fx 는 index.html 이 갖고 있는 것만 씁니다: sonar · hush · boom · thud · static ·
# water · rumble · nightfall.
# ★ alarm(사이렌)은 걷어냈습니다. 이 세상에는 경찰도 구급차도 없어서, 사이렌은
#   «어디선가 누가 오고 있다»는 소리인데 여기엔 올 사람이 없습니다. 그 한 소리에
#   화면은 새벽 지붕인데 귀만 도시 한복판이 됐습니다. 자리를 이어받은 것이 boom 입니다.
#
# ★ 일렁임은 언제나 img "shimmer" · fx "static" 입니다. **오프닝에서는 빠졌습니다** —
#   그 복선은 이제 데이빗의 알리바이 증언(ALIBI_LOG)과 `E1 일렁임의 잔상`이 집니다.
#   개발자 전환(EVENT_CUTS["dev"])에서 같은 그림 같은 소리로 처음 화면에 뜹니다.
#
# ★ **16컷에서 9컷으로 줄였습니다.** 마을 소개(이 세상의 규칙 · 오로라 · 관리자 소개)
#   블록을 통째로 뺐습니다 — 그건 조사카드가 할 일입니다(`E2 오로라 하늘` ·
#   `F1 폐기된 규칙들` · `B8 마을주민 장부`). 오프닝에서 미리 말해 버리면 그 카드를
#   뽑았을 때 값이 떨어집니다. 세계 설명은 `COMMON_INTRO` 가 이미 지고 있습니다.
#
