def role_cut(role_id: str, key: str):
    """배역 몫의 컷. 엔진이 «그 사람에게만» 내려보냅니다.

    지금은 1차 범인지목 직후(after1) 한 자리뿐입니다. 없는 자리면 None.
    """
    if key == (DEV_PICK.get("cutAll") or "after1"):
        return AFTER_VOTE_CUTS.get(role_id)
    return None


