# 방탈출 «문에 꽂는» 도구 목록. 손으로 두 곳에 적으면 반드시 어긋나므로 뽑아서 씁니다.
# **셋이어야 합니다** — 회색조작기(C1) · 게임팩(H0) · 전기(C5).
#
# ★ 정본이 카드의 `item` 이 아니라 **문의 자리표(`ESCAPE["answer"]`)** 입니다.
#   `item` 은 「상한 없는 인벤토리에 들어간다」는 표일 뿐이고, 그게 붙었다고 다 문에
#   꽂히는 것은 아닙니다 — 확성기(C6)가 그렇습니다. 데이지가 쥐고 시작하는 물건이라
#   인벤토리에는 들어가야 하지만, 문의 자리는 셋 그대로여야 순열이 여섯으로 남습니다.
#   ※ 나가는 것은 개수뿐입니다(`/api/state` 의 `itemNeed`). 자리표는 안 나갑니다.
# 열쇠 반쪽(KEY_HALVES)도 여기 안 들어옵니다. 그건 문에 꽂는 것이 아니라 입장권입니다.
ESCAPE_ITEMS = [ESCAPE["answer"][s["id"]] for s in ESCAPE["slots"]
                if s["id"] in ESCAPE["answer"]]

# 배점표의 질문지 요약을 문항 쪽 값으로 다시 맞춥니다 — 두 곳에 적힌 숫자가
# 어긋나는 것이 이런 파일에서 제일 흔한 사고입니다.
SCORE_RULES["questions"] = {q["id"]: int(q.get("points", 0))
                            for q in FINAL_QUESTIONS if not q.get("draft")}


# ══════════════════════════════════════════════════════════════════
#  아래는 엔진이 부르는 인터페이스입니다. 대개 손대지 않아도 됩니다.
# ══════════════════════════════════════════════════════════════════
def get_character(cid: str):
    return next((c for c in CHARACTERS if c["id"] == cid), None)


def get_npc(cid: str):
    return next((n for n in NPCS if n["id"] == cid), None)


def get_card(cid: str):
    return next((c for c in CARDS if c["id"] == cid), None)


def obligatory_cards_upto_round(rnd: int) -> list:
    return [c["id"] for c in CARDS if c.get("reveal") == "obligatory" and c["round"] <= rnd]


def public_card(cid: str):
    """전체공개된 카드로 나가는 몫. 여기 안 적은 필드는 플레이어에게 안 갑니다.

    ★ 퍼즐에서 나가는 것은 `prompt` 뿐입니다.
      `answer` 는 당연하고, **`hint` 도 안 나갑니다** — 「막히면 주는 한 줄」이
      처음부터 보이면 퍼즐이 그냥 읽는 글이 됩니다. 몇 번 틀린 사람에게만 열어주는
      배선은 엔진 쪽 일이고, 그때도 개인 칸으로만 내려갑니다(puzzle_hint 참고).
    """
    c = get_card(cid)
    if not c:
        return None
    out = {"id": c["id"], "loc": c["loc"], "locName": c["locName"], "round": c["round"],
           "title": c["title"], "text": c["text"], "bait": c.get("bait", False),
           "spot": c.get("spot", ""), "unlocks": c.get("unlocks", ""),
           # 손패 상한 밖의 물건 둘. 화면이 「카드」와 「도구」를 이 두 표로 가른다 —
           # keyHalf 를 안 실어 보냈더니 열쇠 반쪽이 카드 칸에 들어가서, 서버가
           # 세는 장수와 화면이 세는 장수가 어긋났다.
           "item": bool(c.get("item")), "keyHalf": bool(c.get("keyHalf"))}
    p = c.get("puzzle")
    if p:
        out["puzzle"] = {"prompt": p.get("prompt", "")}
    return out


def puzzle_hint(cid: str) -> str:
    """막힌 사람에게만 열어주는 한 줄. 엔진이 「몇 번 틀렸는가」를 세고 부릅니다.

    `public_card()` 로는 절대 안 나갑니다 — 그래서 이 함수가 따로 있습니다.
    """
    p = (get_card(cid) or {}).get("puzzle") or {}
    return p.get("hint", "")


def check_puzzle(cid: str, got: str) -> bool:
    """암호 판정. **반드시 서버에서** 합니다.

    한글은 완성형(U+AC00)과 자모 조합(U+1100 U+1161)이 눈으로 같고 `==` 로 다릅니다 —
    안드로이드 키보드와 맥 IME 가 서로 다르게 보냅니다. NFC 로 모으고, 공백을 전부
    빼고, 소문자로 내립니다. 정답이 숫자만이면 입력에서도 숫자만 남깁니다.
    그 이상은 안 합니다 — 흔들림을 다 받아주려면 규칙이 끝없이 늡니다.
    대신 `answer` 를 목록으로 받아 해결합니다.
    """
    import re
    import unicodedata

    def norm(s):
        s = unicodedata.normalize("NFC", str(s or ""))
        return re.sub(r"\s+", "", s).lower()

    p = (get_card(cid) or {}).get("puzzle") or {}
    want = p.get("answer")
    if want is None:
        return False
    wants = want if isinstance(want, (list, tuple)) else [want]
    for w in wants:
        w2 = norm(w)
        g2 = norm(got)
        if w2.isdigit():
            g2 = "".join(ch for ch in g2 if ch.isdigit())
        if w2 and w2 == g2:
            return True
    return False


def private_notes(role_id: str, card_id: str) -> list:
    """그 배역에게만 붙는 카드 메모.

    **카드 본문은 모두에게 같고, 여기서 나오는 한 줄만 다릅니다.** 그게 이 판의
    「같은 것을 봐도 누가 보느냐에 따라 뜻이 늘어난다」입니다 —
    균열 결은 데이빗에게, 도구 결은 데이지에게, 자기 흔적은 데이먼에게.

    남의 몫은 애초에 만들지 않습니다. 배역이 없으면(관전·진행석) 빈 손입니다.
    """
    if not role_id:
        return []
    return list((PRIVATE_NOTES.get(role_id) or {}).get(card_id) or [])


def phase_by_seq(seq: int) -> dict:
    return next((p for p in PHASES if p["seq"] == seq), PHASES[-1])


def interlude_for(seq: int):
    return INTERLUDES.get(seq)


# 「조용히 받는 것」에 붙는 이름표. 막 이름과 «달라야» 합니다 — 서버의 막머리 처리
# (`_seed_phase_lines`)가 「when 이 지금 막 이름과 같은 것」만 대화창에 올리기 때문에,
# 이 이름표를 달면 그 줄은 대화창을 타지 않고 「내 정보」에만 남습니다.
QUIET_LABEL = "혼자 떠오른 것"


def memory_up_to(cid: str, current_seq: int, crisis_solved=None) -> list:
    """그 배역에게 지금까지 떠오른 것.

    ★ `quiet: True` 인 항목은 **대화창에 안 올라갑니다.** 2차 토론 뒤에 셋이 동시에
      받는 것들이 그렇습니다 — 세상의 끝 앞의 기억도, 데이지의 공략도 «혼자 읽는»
      것이라야 위장이 성립합니다. 자동으로 대화창에 흘러버리면 그 자리에서 다 새고,
      데이빗이 그걸 숨기고 싶어 한다는 설정도 무의미해집니다.

      엔진을 안 고치고 이걸 만드는 길이 이름표입니다 — `when` 을 막 이름이 아닌
      `QUIET_LABEL` 로 돌려주면 막머리 처리가 그 줄을 그냥 지나칩니다.
      「내 정보」의 조각 목록은 이 함수의 결과를 통째로 쓰므로 거기에는 그대로 뜹니다.
    """
    out = []
    for m in MEMORY.get(cid, []):
        if m["seq"] <= current_seq:
            when = QUIET_LABEL if m.get("quiet") else phase_by_seq(m["seq"])["name"]
            out.append({"when": when, "text": m["text"]})
    return out


def private_sheet(cid: str):
    """그 배역 본인만 보는 롤카드.

    ★ 개발자 전환으로 갈아 끼우는 몫(DEV_PICK["sheet"])은 **여기서 안 덮습니다.**
      이 함수는 방 상태를 모르고, 모듈 전역에 방을 심으면 사건을 갈아 끼웠을 때
      옛 값이 남습니다. 덮어쓰기는 서버의 `/api/sheet/{role_id}` 가 합니다 —
      그 창구는 clientId 를 엄격히 검사하니 본인 말고는 못 봅니다.
    """
    c = get_character(cid)
    if not c:
        return None
    return {"id": c["id"], "name": c["name"], "job": c["job"], "avatar": c.get("avatar", ""),
            "color": c["color"], "hidden": c.get("hidden", False), "persona": c["persona"],
            "sex": c.get("sex", ""), "age": c.get("age", ""), "look": c.get("look", ""),
            "goals": c.get("goals", []), "tips": c.get("tips", []),
            "hook": c.get("hook", ""), "storyPast": c.get("storyPast", ""),
            "storyToday": c.get("storyToday", ""), "hide": c.get("hide", []),
            "past": c.get("past", []),
            "knows": [{"id": x["id"], "title": x["title"], "locName": x["locName"],
                       "loc": x["loc"], "spot": x.get("spot", ""), "text": x["text"],
                       "round": x.get("round", 1)}
                      for x in (get_card(k) for k in (c.get("knows") or [])) if x],
            "map": MAP}


def public_scenario() -> dict:
    """모두가 같이 받는 몫. 여기 없는 것은 화면에 아예 안 뜹니다.

    ★ 여기 실으면 안 되는 것: DEV_PICK · PRIVATE_NOTES · ESCAPE["answer"] ·
      ESCAPE["code"]["answer"] · ZONE_GATES[…]["open"] · puzzle 의 answer 와 hint ·
      **FINAL_QUESTIONS 의 correct / bonus / correctIsDev / noDevKey**.
      전부 아래에 없습니다.
    """
    return {
        "title": TITLE, "subtitle": SUBTITLE, "intro": COMMON_INTRO, "victim": VICTIM,
        "alibiLog": ALIBI_LOG, "alibiNote": ALIBI_NOTE, "alibiHead": ALIBI_HEAD,
        "map": [{"loc": z["loc"], "name": z["name"], "icon": z.get("icon", ""),
                 # 어느 구역에서 이어지는 자리인가. 여는 «조건» 은 안 나갑니다.
                 "opensFrom": z.get("opensFrom", "")} for z in MAP],
        "board": BOARD,
        "pins": PINS,
        "victimCard": VICTIM_CARD, "sceneNote": SCENE_NOTE,
        "mapLabel": "마을 지도",
        # ★ art2/art2At 은 그 표를 «든 방만» 싣습니다. 안 갈리는 방에 빈 칸을 얹어
        #   보내면 화면이 「여기도 갈리는 방」으로 읽을 여지를 남깁니다.
        "rooms": [{"key": r["key"], "loc": r["loc"], "name": r["name"], "art": r["art"],
                   "needPod": False,
                   **({"art2": r["art2"], "art2At": int(r.get("art2At", 0))} if r.get("art2") else {})}
                  for r in ROOMS],
        # 잠긴 구역에서 읽히는 줄. **여는 조건은 절대 안 담습니다.**
        "sealedWhy": {k: g.get("why", "") for k, g in ZONE_GATES.items()},
        # 화면의 이름표. 이 게임은 「어제/오늘」로 굴러갑니다.
        "storyLabels": {"past": "지난 과거", "today": "오늘, 일어난 일",
                        "when": "오늘", "goals": "오늘, 내가 노리는 것",
                        "pastTl": "그날부터 오늘까지"},
        "victimStages": VICTIM_STAGES,
        # 1차 지목에서 자기 이름을 적을 수 있는가. 화면이 이 값을 보고 내 이름을
        # 목록에서 뺍니다 — 못 누르게만 해 두면 「왜 안 눌리지」가 되고, 규칙표에도
        # 이 한 줄이 같이 섭니다.
        "accuseSelf": ACCUSE_SELF,
        "fragLabel": FRAGMENT_LABEL, "fragEyebrow": FRAGMENT_EYEBROW,
        "fragNotice": FRAGMENT_NOTICE,
        # round 도 같이 내보냅니다 — 조사 라운드 탭이 이걸 읽습니다.
        # ★ skipUnless 는 안 내보냅니다. 「이 막이 왜 안 떴는가」가 화면에 보이면
        #   열쇠 반쪽을 못 모았다는 것이 그 자리에서 공지됩니다.
        "phases": [{"seq": p["seq"], "key": p["key"], "name": p["name"], "min": p["min"],
                    "ap": p["ap"], "round": p["round"], "gm": p["gm"]} for p in PHASES],
        # ★ **배역 선택창에 나이가 안 뜹니다.** 이 사건에서는 나이 자체가 단서라
        #   고르는 자리에서 미리 보이면 안 됩니다 — 「셋 중 하나만 나이를 댈 수 있다」가
        #   게임 안에서 드러나야 합니다(AGE_INPUT 위의 주석). 그래서 여기서만 빈 값입니다.
        #   롤카드(private_sheet)에는 그대로 나갑니다.
        "characters": [{"id": c["id"], "name": c["name"], "age": "",
                        "job": c["job"], "avatar": c.get("avatar", ""), "color": c["color"],
                        "tagline": c["tagline"], "look": c.get("look", c["tagline"]),
                        "known": c.get("known", "")} for c in CHARACTERS],
        # 이 배역은 입장할 때 본인이 나이를 적습니다. 화면이 그 칸을 띄우라고 알립니다.
        "ageInput": list(AGE_INPUT),
        "npcs": [{"id": n["id"], "name": n["name"], "age": n.get("age", ""), "job": n["job"],
                  "color": n["color"], "tagline": n["tagline"], "look": n.get("look", ""),
                  "known": n.get("known", ""), "note": n.get("note", "")} for n in NPCS],
        "pairKeys": [],
        # item · locked 는 현황판이 「도구」와 「잠긴 카드」를 구분해 그리라고 내보냅니다.
        # 퍼즐의 정답도 힌트도 여기 안 실립니다 — 있다/없다만.
        # vein 은 결(사건 / 균열 / 도구) 표시입니다. 결은 감출 것이 아닙니다 —
        # 어느 결이 무슨 뜻인지는 앉은 사람이 게임 안에서 알아냅니다.
        "cardCatalog": [{"id": c["id"], "loc": c["loc"], "locName": c["locName"],
                         "spot": c.get("spot", ""), "round": c["round"],
                         "auto": bool(c.get("auto")), "hot": bool(c.get("hot")),
                         "gone": c.get("gone", 0),
                         "vanish": c.get("vanish", 0),
                         "item": bool(c.get("item")),
                         "locked": bool(c.get("puzzle")),
                         "requires": c.get("requires", "")} for c in CARDS],
        "openingCuts": OPENING_CUTS,
        # ★ 질문지는 **정답도 배점도 뺀 판본**으로 나갑니다(final_questions_public).
        #   FINAL_QUESTIONS 를 그대로 실으면 correct 가 통째로 새어 나갑니다.
        #   ※ 「공개됐는가」는 여기가 아니라 `/api/state` 의 `finalSheet` 가 정합니다.
        "finalQuestions": final_questions_public(),
        # 조사 라운드 탭이 읽는 것. 이게 있으면 화면이 라운드 수를 추측하지 않습니다.
        "apByRound": {str(k): v for k, v in AP_BY_ROUND.items()},
        "roundNames": {"1": "1차", "2": "2차", "3": "3차"},
        "interludes": {str(k): v for k, v in INTERLUDES.items()},
        # 방탈출 화면이 그릴 몫. **answer 와 code.answer 는 안 나갑니다.**
        "escape": {"need": ESCAPE["need"], "eachOne": ESCAPE["eachOne"],
                   "intro": ESCAPE["intro"],
                   "slots": [{"id": s["id"], "label": s["label"], "note": s.get("note", "")}
                             for s in ESCAPE["slots"]],
                   "codePrompt": ESCAPE["code"]["prompt"]},
    }


# ── 막이 바뀔 때 · 일이 벌어질 때 뜨는 컷 ────────────────────────
def event_cut(key: str):
    """엔진이 「phase:{seq}」·「gate:{loc}」·「vanish」·「dev」·「escape:ok」·
    「ending:{키}」 같은 키로 부릅니다. 없는 키면 None 을 돌려주면 됩니다.

    엔딩 컷은 **엔딩이 확정되는 순간**에 불러야 합니다. 막에 들어서는 시점에는
    아직 표가 다 안 모여 엔딩이 None 일 수 있습니다.
    """
    if key.startswith("ending:"):
        return ENDING_CUTS.get(key.split(":", 1)[1])
    return EVENT_CUTS.get(key)


# ── 개발자 전환 판정 ─────────────────────────────────────────────
def dev_pick_from(picks: dict, asked=None, held=None) -> str:
    """개발자가 누구에게 로그인하는가.

    **「진상에 가까운 답」 = 「이 세상이 게임임에 가까이 간 답」입니다.** 깨달으면
    그게 버그이므로 덮어씁니다 — 그게 이 판정의 전부입니다.

    `picks`  {배역id: 선지id} — 폴백 선지에서 고른 것.
             ★ **정본은 1차 범인지목의 표입니다**(DEV_FROM_ACCUSE · DEV_PICK["byVote"]).
             이 함수는 그 배선이 없을 때만 씁니다.
    `asked`  [{"by","q"}]     — 질문지 기록. 선지가 아직 안 붙어 있는 동안의 보조 축.
    `held`   {배역id: [카드id]} — 쥐었거나 공개한 것. 같은 보조 축.

    `pool` 밖(데이지)은 애초에 안 셉니다 — 캐릭터가 아니라 플레이어라서
    접속할 대상이 아닙니다(DEV_PICK["poolWhy"]). 동점이면 `tiebreak`.
    """
    pool = list(DEV_PICK["pool"])
    score = {rid: 0 for rid in pool}
    for rid, oid in (picks or {}).items():
        if rid not in score:
            continue
        opt = next((o for o in DEV_PICK["options"] if o["id"] == oid), None)
        if opt:
            score[rid] += int(opt.get("near", 0))
    for row in (asked or []):
        rid = row.get("by")
        if rid in score:
            score[rid] += int(DEV_PICK["qw"].get(row.get("q"), 0))
    for rid, cards in (held or {}).items():
        if rid not in score:
            continue
        for cid in cards or []:
            score[rid] += int(DEV_PICK["cw"].get(cid, 0))
    top = max(score.values()) if score else 0
    lead = sorted(r for r, v in score.items() if v == top)
    if len(lead) == 1:
        return lead[0]
    return DEV_PICK["tiebreak"]


# ── 질문지 ───────────────────────────────────────────────────────
def final_questions_public() -> list:
    """질문지에서 **화면으로 나가는 몫**.

    `correct` · `bonus` · `points` · `correctIsDev` · `noDevKey` 는 여기서 통째로
    빠집니다 — 한 줄이라도 새면 질문지가 그냥 읽는 글이 됩니다. 배점도 안 내보냅니다:
    화면이 그대로 읽어 버립니다.

    `draft: True` 인 문항(=아직 안 정한 것)은 아예 안 내보냅니다. **그래서 답안
    배열의 순서는 FINAL_QUESTIONS 가 아니라 이 함수의 결과 순서입니다.**
    """
    out = []
    for q in FINAL_QUESTIONS:
        if q.get("draft"):
            continue
        row = {"id": q["id"], "q": q["q"],
               "options": [{"id": o["id"], "label": o["label"]} for o in q.get("options", [])]}
        if q.get("note"):
            row["note"] = q["note"]
        out.append(row)
    return out


def score_final_answers(answers: dict, dev_id: str = "") -> dict:
    """질문지를 채점한다. **반드시 서버에서** 부릅니다.

    `answers`  {배역id: {문항id: 고른 선지id}}
               — **목록으로 줘도 됩니다.** `{배역id: [선지id, …]}` 는
               `final_questions_public()` 의 순서로 읽습니다(화면이 그 순서로 올립니다).
    `dev_id`   그 게임의 개발자 배역 id. **개발자가 안 들어온 게임이면 빈 문자열**입니다
               (§7-h — 데이지가 최다 득표거나 1:1:1 이면 아무도 안 들어옵니다).

    돌려주는 것 —
      points   {배역id: 질문지에서 얻은 점수}          ※ 개발자 몫은 여기서 0입니다
      hits     {문항id: [맞힌 배역id]}
      devHits  개발자를 맞힌 사람 수 (Q2)
      devScore 개발자 점수를 어떻게 셀지 — 밑돈은 **다른 둘의 «최종» 점수 합**이라
               여기서는 못 셉니다. 감점만 계산해 돌려주고, 합은 서버가 얹습니다.

    ★ 개발자의 최종 점수 = 다른 두 사람의 최종 점수 합 + `devScore["penalty"]`.
      `floor` 가 숫자면 그 아래로는 안 내려갑니다.
    """
    order = [q["id"] for q in final_questions_public()]
    qs = {q["id"]: q for q in FINAL_QUESTIONS if not q.get("draft")}
    points = {rid: 0 for rid in (answers or {})}
    hits = {qid: [] for qid in qs}
    for rid, sheet in (answers or {}).items():
        if isinstance(sheet, (list, tuple)):          # 화면이 올리는 순서 배열
            sheet = dict(zip(order, sheet))
        for qid, q in qs.items():
            got = (sheet or {}).get(qid)
            if not got:
                continue
            ok = got in (q.get("correct") or [])
            if q.get("correctIsDev"):
                # 개발자가 든 판이면 그 배역만, 안 든 판이면 「들어오지 않았다」만 정답.
                ok = (got == dev_id) if dev_id else (got == q.get("noDevKey"))
            if not ok:
                continue
            hits[qid].append(rid)
            points[rid] += int(q.get("points", 0)) + int((q.get("bonus") or {}).get(got, 0))
    # 개발자 자신은 자기 점수를 못 얻습니다 — 남이 만들어 줍니다.
    if dev_id in points:
        points[dev_id] = 0
    dev_q = next((q["id"] for q in FINAL_QUESTIONS if q.get("hitsDev")), "q2")
    dev_hits = len([r for r in hits.get(dev_q, []) if r != dev_id])
    rule = SCORE_RULES.get("dev") or {}
    return {"points": points, "hits": hits, "devHits": dev_hits,
            "devScore": {"base": "sum_others",
                         "penalty": dev_hits * int(rule.get("penalty_per_hit", -20)),
                         "floor": rule.get("floor"),
                         "formula": rule.get("formulaKo", "")} if dev_id else None}


# ── 엔딩 선지 판정 ───────────────────────────────────────────────
def judge_ending_picks(picks: dict, dev_id: str = "") -> dict:
    """마지막 질문(10막)의 선지를 읽는다.

    `picks`  {배역id: 선지id}
    `dev_id` 개발자에게 먹힌 사람(있으면). 그 사람의 답은 판정에서 뺍니다 —
             자기가 아는 것을 고르는 것은 「닿았다」가 아닙니다.

    돌려주는 것 —
      seen     이 세상이 무엇인지 «닿은» 배역 id 목록
      devKept  먹힌 사람 말고 **다른 둘이 끝내 못 닿았는가**. 개발자 단독 우승 조건

    ★ 이 판본의 PHASES 에는 `decision` 막이 없습니다. 그래서 `picks` 가 비어서
      들어오는 것이 정상이고, **그때는 아무것도 판정하지 않습니다** — 빈 표를
      「아무도 못 닿았다」로 읽으면 개발자가 가만히 있어도 단독 우승합니다.
      개발자 축의 판정은 질문지 Q2(`score_final_answers`)가 집니다.
    """
    opt = {o["id"]: o for o in ENDING_OPTIONS}
    seen = sorted(rid for rid, oid in (picks or {}).items()
                  if opt.get(oid, {}).get("sees"))
    others = [rid for rid in (picks or {}) if rid != dev_id]
    dev_kept = bool(dev_id) and bool(others) and \
        all(not opt.get(picks[r], {}).get("sees") for r in others)
    return {"seen": seen, "devKept": dev_kept}


# ── 방 상태 받아 두기 ─────────────────────────────────────────────
# 서버가 bump() 할 때마다 「지금 방이 이렇다」를 넣어 줍니다. compute_ending 이
# ctx 를 못 받는 옛 엔진에서도 진엔딩 판정이 서게 하려는 폴백입니다.
_ROOM: dict = {}


def set_room_state(st: dict) -> None:
    _ROOM.clear()
    _ROOM.update(st or {})


def title_for(role_id: str, points: int, ctx=None) -> str:
    """그 배역이 그 점수로 받는 칭호. 구간표에서 위에서부터 처음 맞는 것을 씁니다."""
    for row in TITLES.get(role_id, []):
        if points >= int(row.get("min", 0)):
            return row.get("t", "")
    return ""


# ── 엔딩 ─────────────────────────────────────────────────────────
def compute_ending(votes: dict, ctx=None):
    """엔딩을 고른다.

    `votes` 는 `{지목한 배역id: 지목당한 배역id}`.
    `ctx`   는 엔진이 넘겨주는 방 상태입니다(안 넘겨주는 엔진도 있어서 기본값 None).

        {"escape":  {"done": True/False},          방탈출 성패
         "decision": {배역id: 선지id},              마지막 질문의 답
         "dev":      {"who": 배역id},               개발자에게 먹힌 사람
         "items":    {배역id: [카드id]},            인벤토리
         "solved":   {카드id: 배역id}}              푼 퍼즐

    갈리는 순서 —
      1. 문이 열렸는가
         1-1. 열렸는데 다른 둘이 끝내 «못 닿았다»  →  개발자 단독 우승
         1-2. 열렸고 누군가 닿았다                →  진엔딩(전원 탈출)
      2. 안 열렸는데 진범을 맞혔는가              →  잡았으나 갇힘
      3. 그 외                                    →  아무것도 못 밝힘

    **탈출이 지목보다 위에 있습니다.** 그게 「각자 자기 점수를 포기해야 열린다」의 뜻입니다.
    """
    if len(votes) < len(CHARACTERS):
        return None
    ctx = ctx or {}
    tally = {}
    for t in votes.values():
        tally[t] = tally.get(t, 0) + 1
    top = max(tally.values())
    lead = sorted(t for t, v in tally.items() if v == top)
    # 표가 갈리면 아무도 안 잡힌 것으로 본다. 「제일 많이 불린 이름」이 하나여야 검거다.
    caught = (len(lead) == 1 and lead[0] == CULPRIT_ID)

    escaped = _escaped(ctx)
    dev_id = (ctx.get("dev") or {}).get("who", "")
    judged = judge_ending_picks(ctx.get("decision") or {}, dev_id)

    if escaped and judged["devKept"]:
        key = "dev"
    elif escaped:
        key = "escape"
    elif caught:
        key = "caught"
    else:
        key = "dark"
    e = ENDINGS[key]
    hit = sorted(rid for rid, t in votes.items() if t == CULPRIT_ID)
    return {"key": key, "name": e["name"], "tone": e["tone"], "desc": e["desc"],
            "culprit": CULPRIT_ID, "tally": tally, "lead": lead,
            "accused": hit, "truth": TRUTH_FULL,
            "escaped": escaped, "seen": judged["seen"],
            "titlesNote": TITLES_NOTE}


def _escaped(ctx=None) -> bool:
    """문이 열렸는가.

    엔진이 `ctx["escape"]["done"]` 을 넘겨주면 그것이 정본입니다. 아직 방탈출 판정이
    안 붙었으면 `set_room_state` 로 받아둔 인벤토리로 «도구는 다 모였는가»까지만
    봅니다 — 그것도 없으면 False 라서 **진엔딩이 안 열립니다.** 그게 지금 상태입니다.
    """
    ctx = ctx or {}
    esc = ctx.get("escape") or _ROOM.get("escape") or {}
    if esc.get("done") is not None:
        return bool(esc.get("done"))
    inv = ctx.get("items") or _ROOM.get("items") or _ROOM.get("inventory") or {}
    try:
        got = {cid for ids in inv.values() for cid in ids}
    except Exception:                       # noqa: BLE001 — 판정 하나 때문에 게임이 죽으면 안 된다
        return False
    return set(ESCAPE["answer"].values()) <= got


# ── 마지막 질문(10막)의 결과문 ───────────────────────────────────
def decision_report(picks: dict, extra: str = "none", barred: str = "") -> dict:
    """엔진이 「다 골랐다」고 판단했을 때 부릅니다. 화면에 읽히는 몫입니다.

    ※ 여기서 «판정 결과»를 말하지 않습니다 — 누가 무엇에 닿았는지는 엔딩에서
       한꺼번에 나옵니다. 여기서는 각자 무엇을 골랐는지만 되읽어 줍니다.
    """
    opt = {o["id"]: o for o in ENDING_OPTIONS}
    rows = []
    for c in CHARACTERS:
        oid = (picks or {}).get(c["id"], "")
        rows.append({"roleId": c["id"], "name": c["name"], "color": c["color"],
                     "label": opt.get(oid, {}).get("label", "—")})
    return {"title": "마지막으로 남긴 문장",
            "lines": [f'{r["name"]} — {r["label"]}' for r in rows],
            "rows": rows}


